// Zwei Dinge passieren hier bewusst VOR der KI:
// 1. Eine eigene Stichwortpruefung auf die typischen Anhang-III-Bereiche. Wenn
//    die KI spaeter harmloser einstuft als diese Heuristik, faellt das auf -
//    ein Modell allein soll nicht das einzige Sicherheitsnetz sein.
// 2. Eine stabile Meldung-ID, damit sich Inventar-Zeile, Mail und spaetere
//    Pruefung eindeutig zuordnen lassen.
const anhangIII = [
  { kategorie: 'Beschaeftigung und Personalauswahl (Anhang III Nr. 4)', begriffe: ['bewerb', 'recruit', 'personalauswahl', 'lebenslauf', 'cv-screening', 'befoerder', 'kuendig', 'leistungsbeurteil', 'mitarbeiterbewert', 'schichtzuteil'] },
  { kategorie: 'Biometrie (Anhang III Nr. 1)', begriffe: ['biometr', 'gesichtserkenn', 'fingerabdruck', 'emotionserkenn', 'stimmerkennung'] },
  { kategorie: 'Kreditwuerdigkeit und Versicherung (Anhang III Nr. 5)', begriffe: ['bonitaet', 'kreditwuerdig', 'scoring', 'schufa', 'risikopraemie', 'versicherungstarif'] },
  { kategorie: 'Bildung und Pruefung (Anhang III Nr. 3)', begriffe: ['pruefungsbewert', 'noten', 'zulassung', 'ausbildungsplatz', 'lernstands'] },
  { kategorie: 'Kritische Infrastruktur (Anhang III Nr. 2)', begriffe: ['stromnetz', 'wasserversorgung', 'verkehrssteuerung', 'kritische infrastruktur', 'gasnetz'] },
  { kategorie: 'Zugang zu wesentlichen Diensten (Anhang III Nr. 5)', begriffe: ['sozialleistung', 'notruf', 'triage', 'anspruchspruefung'] },
  { kategorie: 'Strafverfolgung und Migration (Anhang III Nr. 6 und 7)', begriffe: ['strafverfolg', 'polizei', 'asyl', 'migration', 'grenzkontrolle'] }
];

const raus = [];
for (const eintrag of $input.all()) {
  const f = eintrag.json || {};
  const system = String(f['System / Anwendung'] || '').trim();
  const zweck = String(f['Zweck / Einsatzbereich'] || '').trim();
  const datenarten = String(f['Verarbeitete Datenarten'] || '').trim();
  const suchtext = (system + ' ' + zweck + ' ' + datenarten).toLowerCase();

  const treffer = anhangIII.filter(k => k.begriffe.some(b => suchtext.includes(b))).map(k => k.kategorie);

  const entscheidungswirkung = String(f['Wirkt das System auf Entscheidungen ueber Menschen?'] || 'Unklar');
  const sichtbarkeit = String(f['Ausgaben sind fuer Externe sichtbar?'] || 'Nein, nur intern');

  // Externer Dialog oder nach aussen gehende KI-Inhalte loesen die
  // Transparenzpflicht nach Art. 50 aus - das ist keine Ermessensfrage.
  const transparenzrelevant = sichtbarkeit.startsWith('Ja');

  const laufnummer = String(Date.now()).slice(-6);
  raus.push({
    json: {
      meldung_id: 'KI-' + new Date().getFullYear() + '-' + laufnummer,
      gemeldet_am: new Date().toLocaleDateString('de-DE'),
      abteilung: String(f['Abteilung'] || '').trim(),
      ansprechpartner: String(f['Ansprechpartner (E-Mail)'] || '').trim(),
      system,
      anbieter: String(f['Anbieter'] || '').trim(),
      zweck,
      datenarten,
      betroffene: String(f['Betroffene Personengruppen'] || ''),
      rechtsgrundlage: String(f['Rechtsgrundlage der Verarbeitung'] || ''),
      entscheidungswirkung,
      sichtbarkeit,
      transparenzrelevant,
      heuristik_anhang_iii: treffer.length > 0,
      heuristik_kategorien: treffer.join('; '),
      rechtsgrundlage_unklar: String(f['Rechtsgrundlage der Verarbeitung'] || '').startsWith('Unklar')
    }
  });
}
return raus;

