// Der KI-Vorschlag wird hier nicht einfach uebernommen, sondern geprueft:
// 1. Nur die vier zulaessigen Klassen sind erlaubt, alles andere wird zu
//    unklar_manuelle_pruefung - eine halluzinierte Klasse darf nicht ins
//    Inventar wandern.
// 2. Wenn die eigene Stichwortpruefung Anhang III trifft, die KI aber
//    harmloser einstuft, gewinnt die strengere Bewertung. Untertreiben ist
//    hier das teurere Risiko.
// 3. Externe KI-Ausgaben loesen die Transparenzpflicht nach Art. 50 aus,
//    unabhaengig davon, was das Modell geantwortet hat.
const ERLAUBT = ['verboten', 'hochrisiko_anhang_iii', 'transparenzpflicht_art_50', 'minimales_risiko'];
const KLARTEXT = {
  verboten: 'Verbotene Praktik (Art. 5) - Einsatz sofort stoppen',
  hochrisiko_anhang_iii: 'Hochrisiko nach Anhang III',
  transparenzpflicht_art_50: 'Transparenzpflicht nach Art. 50',
  minimales_risiko: 'Minimales Risiko',
  unklar_manuelle_pruefung: 'Unklar - manuelle Pruefung erforderlich'
};

const meldung = $('Meldung aufbereiten').item.json;
const v = $input.first().json.message?.content ?? $input.first().json;

let klasse = String(v.risikoklasse || '').trim().toLowerCase();
const korrekturen = [];
if (!ERLAUBT.includes(klasse)) {
  korrekturen.push('KI lieferte eine unbekannte Klasse (' + (v.risikoklasse || 'leer') + ')');
  klasse = 'unklar_manuelle_pruefung';
}

if (meldung.heuristik_anhang_iii && klasse !== 'verboten' && klasse !== 'hochrisiko_anhang_iii') {
  korrekturen.push('Stichwortpruefung deutet auf Anhang III hin (' + meldung.heuristik_kategorien + '), Vorschlag wurde hochgestuft');
  klasse = 'hochrisiko_anhang_iii';
}

if (meldung.transparenzrelevant && klasse === 'minimales_risiko') {
  korrekturen.push('Ausgaben sind fuer Externe sichtbar - Transparenzpflicht nach Art. 50 greift zusaetzlich');
  klasse = 'transparenzpflicht_art_50';
}

const pflichten = Array.isArray(v.pflichten) ? v.pflichten.slice() : [];
if (meldung.transparenzrelevant && !pflichten.some(p => /kennzeich|transparenz/i.test(String(p)))) {
  pflichten.push('KI-generierte Inhalte bzw. den KI-Einsatz gegenueber Betroffenen kennzeichnen (Art. 50)');
}
pflichten.push('Ausreichende KI-Kompetenz der nutzenden Personen sicherstellen (Art. 4, gilt seit 02.02.2025)');

const rueckfragen = Array.isArray(v.rueckfragen) ? v.rueckfragen.slice() : [];
if (meldung.rechtsgrundlage_unklar) rueckfragen.push('Rechtsgrundlage der Datenverarbeitung ist ungeklaert - mit dem Datenschutzbeauftragten abstimmen');
if (String(meldung.entscheidungswirkung).startsWith('Unklar')) rueckfragen.push('Entscheidungswirkung auf Personen ist ungeklaert - Prozess mit der Fachabteilung durchgehen');

const sofort_melden = ['verboten', 'hochrisiko_anhang_iii', 'unklar_manuelle_pruefung'].includes(klasse);

return [{
  json: {
    ...meldung,
    risikoklasse: klasse,
    risikoklasse_klartext: KLARTEXT[klasse],
    einschlaegige_kategorie: v.einschlaegige_kategorie || 'keine',
    begruendung: v.begruendung || '',
    gegenargument: v.gegenargument || '',
    sicherheit: v.sicherheit || 'niedrig',
    pflichten: pflichten.join(' | '),
    rueckfragen: rueckfragen.join(' | '),
    frist_hinweis: v.frist_hinweis || 'Art. 4 und Art. 5 seit 02.02.2025, Art. 50 und Anhang III seit 02.08.2026, Anhang I ab 02.08.2027',
    automatische_korrekturen: korrekturen.join(' | '),
    pruefstatus: 'Vorschlag - menschliche Pruefung offen',
    sofort_melden
  }
}];

